-- ═══════════════════════════════════════════════════════════════════════════
-- Asclion — base de conseil v4 : produits conseil + vigilance
--
-- Version par identifiants. La table `medicaments` ne possède pas de colonne
-- nom_molecule (le CSV maître si, mais l'import ne la stocke pas) : le
-- garde-fou moléculaire — celui qui empêche de propager les erreurs de
-- codage ATC de la base — a donc été appliqué en amont, sur le CSV. Les
-- listes d'identifiants ci-dessous en sont le résultat exact.
--
-- COMMENT L'EXÉCUTER
--   Tout coller dans l'éditeur SQL, lancer une fois. Le résultat affiché est
--   celui de la dernière requête : les chiffres de contrôle.
--
-- SÛRETÉ
--   Chaque UPDATE de la partie 1 ne touche que des lignes dont pc_1 est vide,
--   et la condition est répétée dans le WHERE : relancer ne change rien de
--   plus. Le seul bloc qui retire quelque chose est le bloc 0 (nettoyage du
--   hors comptoir, 343 lignes), restaurables depuis
--   asclion_medicaments_conseil_v4.csv.
--
-- Couverture attendue : 79,1 % des lignes réellement délivrées au comptoir,
-- contre 60,2 % avant. 4 538 lignes nouvellement dotées d'un produit conseil.
-- ═══════════════════════════════════════════════════════════════════════════


-- ─── 0. NETTOYAGE — retirer les conseils posés sur du hors comptoir ────────
UPDATE public.medicament_curated_pcs c
SET pc_1 = NULL, pertinence_pc1 = NULL, phrase_conseil_pc1 = NULL,
    pc_2 = NULL, pertinence_pc2 = NULL, phrase_conseil_pc2 = NULL
FROM public.medicaments m
WHERE m.id = c.medicament_id
  AND (m.statut_officine = 'exclu'
       OR coalesce(m.forme_galenique,'') ~* '(perfusion|à diluer|a diluer|dialyse)')
  AND c.pc_1 IS NOT NULL;


