-- ═══════════════════════════════════════════════════════════════════════════
-- PARTIE 2 — LA VIGILANCE
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── V1. Le libellé de niveau, sans lequel le badge disparaît ──────────────
-- L'application lit `pertinence_vigilance` pour afficher « Sécurité » ou
-- « Accompagnement » à gauche de la phrase. Vide, le badge ne s'affiche pas.
UPDATE public.medicament_curated_pcs
SET pertinence_vigilance = 'Sécurité'
WHERE nullif(btrim(coalesce(pertinence_vigilance,'')), '') IS NULL
  AND (nullif(btrim(coalesce(vigilance,'')), '') IS NOT NULL
    OR nullif(btrim(coalesce(phrase_vigilance,'')), '') IS NOT NULL);

-- ─── V2. Que tous les chemins de lecture trouvent la phrase ────────────────
UPDATE public.medicament_curated_pcs
SET vigilance = phrase_vigilance
WHERE nullif(btrim(coalesce(vigilance,'')), '') IS NULL
  AND nullif(btrim(coalesce(phrase_vigilance,'')), '') IS NOT NULL;

-- ─── V3. Dire explicitement pourquoi il n'y a rien à dire ──────────────────
UPDATE public.medicament_curated_pcs c
SET vigilance = 'Produit hospitalier ou non délivré au comptoir : pas de suggestion de conseil associé.',
    pertinence_vigilance = 'Accompagnement'
FROM public.medicaments m
WHERE m.id = c.medicament_id
  AND (m.statut_officine = 'exclu'
       OR m.atc_code ~ '^(V0[13456789]|B05|B02A|B02B|N01A|M03A|J06B|B06A|L01[ACDX])'
       OR coalesce(m.forme_galenique,'') ~* '(perfusion|à diluer|a diluer|dialyse)')
  AND nullif(btrim(coalesce(c.vigilance,'')), '') IS NULL;


-- ─── CONTRÔLE FINAL ────────────────────────────────────────────────────────
SELECT
  count(*)                                                          AS lignes,
  count(*) FILTER (WHERE nullif(btrim(c.pc_1),'') IS NOT NULL)      AS avec_pc1,
  round(100.0*count(*) FILTER (WHERE nullif(btrim(c.pc_1),'') IS NOT NULL)/count(*),1) AS pct,
  count(*) FILTER (WHERE nullif(btrim(c.vigilance),'') IS NOT NULL) AS avec_vigilance,
  count(*) FILTER (WHERE nullif(btrim(c.pertinence_vigilance),'') IS NOT NULL) AS avec_niveau_vigilance
FROM public.medicament_curated_pcs c
JOIN public.medicaments m ON m.id = c.medicament_id
WHERE m.statut_officine = 'actif'
  AND m.atc_code IS NOT NULL
  AND m.atc_code !~ '^(V0[13456789]|B05|B02A|B02B|N01A|M03A|J06B|B06A|L01[ACDX])'
  AND m.atc_code NOT LIKE 'WHOME%'
  AND coalesce(m.forme_galenique,'') !~* '(perfusion|à diluer|a diluer|dialyse)';

-- Attendu :  avec_pc1 ≈ 19 000   pct ≈ 79,1
--            avec_niveau_vigilance = avec_vigilance